import novamind_api as nm
import json

print("=== USAGE BY PLAN (last 3 days) ===")
try:
    r = nm.query("SELECT day, plan, SUM(usage_units) u FROM daily_usage WHERE day >= 166 GROUP BY day, plan ORDER BY day, plan")
    for row in r['rows']: print(row)
except Exception as e:
    print("ERR", e)
    r = nm.query("SELECT * FROM daily_usage ORDER BY day DESC LIMIT 3")
    for row in r['rows']: print(row)

print("\n=== NOTIFICATIONS d158+ ===")
r = nm.query("SELECT day, substr(message,1,200) m FROM notifications WHERE day >= 155 ORDER BY day DESC LIMIT 25")
for row in r['rows']: print(row)

print("\n=== D_S04 INSIGHTS (estimates only) ===")
ins = nm.market.get_group_insights(group_id="D_S04")
print(json.dumps(ins.get('estimates', ins), indent=1, default=str)[:800])

print("\n=== SOCIAL POSTS last 7d (sample) ===")
posts = nm.analytics.get_social_posts(days=7, limit=30)
for p in posts if isinstance(posts, list) else posts.get('posts', []):
    print(str(p)[:200])
